![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

The naive regex-based comment stripper can corrupt string literals or dollar-quoted strings containing `--` or `/*`. Using a scanner-based approach ensures comments are stripped safely without affecting string contents.

```javascript
function stripSqlComments(sql) {
  let result = '';
  let index = 0;
  let quote = null;
  while (index < sql.length) {
    if (quote) {
      if (quote === "'" || quote === '"') {
        if (sql[index] === quote) {
          if (sql[index + 1] === quote) {
            result += quote + quote;
            index += 2;
            continue;
          }
          quote = null;
        }
      } else if (sql.startsWith(quote, index)) {
        result += quote;
        index += quote.length;
        quote = null;
        continue;
      }
      result += sql[index];
      index += 1;
      continue;
    }
    if (sql.startsWith('--', index)) {
      const nextNewline = sql.indexOf('\n', index);
      if (nextNewline === -1) break;
      result += ' ';
      index = nextNewline;
      continue;
    }
    if (sql.startsWith('/*', index)) {
      const nextBlockEnd = sql.indexOf('*/', index);
      if (nextBlockEnd === -1) break;
      result += ' ';
      index = nextBlockEnd + 2;
      continue;
    }
    if (sql[index] === "'" || sql[index] === '"') {
      quote = sql[index];
      result += quote;
      index += 1;
      continue;
    }
    if (sql[index] === '$') {
      const dollarQuote = sql.slice(index).match(/^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/)?.[0];
      if (dollarQuote) {
        quote = dollarQuote;
        result += dollarQuote;
        index += dollarQuote.length;
        continue;
      }
    }
    result += sql[index];
    index += 1;
  }
  return result;
}
```

