function splitTopLevelList(sql) {
  const entries = [];
  let start = 0;
  let depth = 0;
  let quote = null;
  for (let index = 0; index < sql.length; index += 1) {
    if (quote) {
      if (quote === "'" || quote === '"') {
        if (sql[index] === quote) {
          if (sql[index + 1] === quote) index += 1;
          else quote = null;
        }
      } else if (sql.startsWith(quote, index)) {
        index += quote.length - 1;
        quote = null;
      }
      continue;
    }
    if (sql[index] === "'" || sql[index] === '"') {
      quote = sql[index];
    } else if (sql[index] === '$') {
      const dollarQuote = sql.slice(index).match(/^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/)?.[0];
      if (dollarQuote) {
        quote = dollarQuote;
        index += dollarQuote.length - 1;
      }
    } else if (sql[index] === '(') {
      depth += 1;
    } else if (sql[index] === ')') {
      depth -= 1;
    } else if (sql[index] === ',' && depth === 0) {
      entries.push(sql.slice(start, index).trim());
      start = index + 1;
    }
  }
  entries.push(sql.slice(start).trim());
  return entries.filter(Boolean);
}
