The `findTopLevelFrom` function does not support dollar-quoted strings. If a dollar-quoted string contains the word `from`, it will be incorrectly identified as the `FROM` clause. Updating the parser to handle dollar quotes ensures robust parsing of view definitions.

```javascript
function findTopLevelFrom(sql) {
  let depth = 0;
  let quote = null;
  for (let index = 0; index < sql.length; index += 1) {
    if (quote) {
      if (quote === "'" || quote === '"') {
        if (sql[index] === quote) {
          if (sql[index + 1] === quote) index += 1;
          else quote = null;
        }
      } else if (sql.startsWith(quote, index)) {
        index += quote.length - 1;
        quote = null;
      }
      continue;
    }
    if (sql[index] === "'" || sql[index] === '"') {
      quote = sql[index];
    } else if (sql[index] === '$') {
      const dollarQuote = sql.slice(index).match(/^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/)?.[0];
      if (dollarQuote) {
        quote = dollarQuote;
        index += dollarQuote.length - 1;
      }
    } else if (sql[index] === '(') {
      depth += 1;
    } else if (sql[index] === ')') {
      depth -= 1;
    } else if (depth === 0 && /^\sfrom\s/i.test(sql.slice(index))) {
      return index;
    }
  }
  return -1;
}
